'use client';

import Link from 'next/link';
import { useState } from 'react';
import { ArrowRight, Eye, EyeOff, LockKeyhole, Mail, ShieldCheck, Sparkles } from 'lucide-react';
import { useAuth } from '@/components/auth-provider';

const API = process.env.NEXT_PUBLIC_API_URL || 'http://127.0.0.1:8000';
export default function LoginPage() {
  const { signIn } = useAuth(); const [mode, setMode] = useState('login');
  const [form, setForm] = useState({ email: '', password: '', confirm_password: '', name: '', username: '', phone: '', is_diabetic: '' }); const [show, setShow] = useState(false); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async (event) => { event.preventDefault(); setError(''); if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(form.email)) return setError('Enter a valid email address.'); if (!form.password) return setError('Enter your password.'); if (mode === 'register' && form.password.length < 8) return setError('Password must be at least 8 characters.'); if (busy) return; if (new TextEncoder().encode(form.password).length > 72) return setError('Password must be at most 72 UTF-8 bytes.'); if (mode === 'register') { if (form.name.trim().length < 2 || form.name.trim().length > 80) return setError('Full name must contain 2–80 characters.'); if (form.password !== form.confirm_password) return setError('Passwords do not match.'); if (!/[A-Z]/.test(form.password) || !/[a-z]/.test(form.password) || !/[0-9]/.test(form.password)) return setError('Password needs uppercase, lowercase, and a number.'); if (!/^[A-Za-z0-9_]{3,30}$/.test(form.username.trim())) return setError('Username must contain 3–30 letters, numbers, or underscores.'); if (!/^07[0-9]{8}$/.test(form.phone)) return setError('Phone number must start with 07 and contain exactly 10 digits.'); if (form.is_diabetic === '') return setError('Select your diabetes status.'); } setBusy(true);
    try { const res = await fetch(`${API}/api/auth/${mode}`, { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({ ...form, email: form.email.trim(), ...(mode === 'register' ? { is_diabetic: form.is_diabetic === 'yes' } : {}) }) }); const data = await res.json(); if (!res.ok) throw new Error(typeof data.detail === 'string' ? data.detail : Array.isArray(data.detail) ? data.detail.map(item => item.msg).join(' ') : 'Check your email and password requirements.'); signIn(data.access_token, data.dashboard, data.user); } catch (e) { setError(e.message); } finally { setBusy(false); }
  };
  return <main className="auth-page"><div className="auth-orb orb-one"/><div className="auth-orb orb-two"/><section className="auth-showcase"><Link href="/login" className="auth-logo"><span className="auth-wordmark">Diabetic<span>CARE</span></span></Link><div className="auth-copy"><span className="auth-eyebrow"><Sparkles size={14}/> PERSONALIZED CARE, REIMAGINED</span><h1>Your health story deserves a smarter workspace.</h1><p>Securely manage diabetes insights, retinal screenings, wound healing, and nutrition plans in one calm, clear place.</p><div className="auth-points"><span><ShieldCheck size={18}/> Encrypted health workspace</span><span><Sparkles size={18}/> AI-assisted insights for your care team</span></div></div><small className="auth-footnote">© 2026 DiabeticCARE · Research project</small></section><section className={`auth-panel glass-panel ${mode === 'register' ? 'registration-panel' : ''}`}><div className="auth-panel-head"><div><p className="auth-kicker">SECURE ACCESS</p><h2>{mode === 'login' ? 'Welcome back' : 'Create your account'}</h2><p>{mode === 'login' ? 'Sign in to continue to your health workspace.' : 'Start your personalized care journey.'}</p></div></div><form onSubmit={submit} noValidate>{mode === 'register' && <><label>Full name<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Alex Morgan" required/></label><label>Username<input autoComplete="username" value={form.username} onChange={e=>setForm({...form,username:e.target.value})} placeholder="alex_morgan" required/></label><label>Phone number<input type="tel" inputMode="numeric" autoComplete="tel-national" maxLength={10} value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})} placeholder="0771234567" required/><small className="auth-field-help">Starts with 07 · exactly 10 digits</small></label><label>Are you a diabetic patient?<select value={form.is_diabetic} onChange={e=>setForm({...form,is_diabetic:e.target.value})} required><option value="">Select your status</option><option value="yes">Yes, I am a diabetic patient</option><option value="no">No, I am not a diabetic patient</option></select></label></>}<label>Email address<div className="auth-input"><Mail size={17}/><input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} placeholder="you@example.com" required/></div></label><label>Password<div className="auth-input"><LockKeyhole size={17}/><input type={show?'text':'password'} value={form.password} onChange={e=>setForm({...form,password:e.target.value})} placeholder="At least 8 characters" minLength={mode === 'register' ? 8 : 1} required/><button type="button" onClick={()=>setShow(!show)} aria-label={show?'Hide password':'Show password'}>{show?<EyeOff size={17}/>:<Eye size={17}/>}</button></div></label>{mode==='register' && <label>Confirm password<div className="auth-input"><LockKeyhole size={17}/><input type={show?'text':'password'} autoComplete="new-password" value={form.confirm_password} onChange={e=>setForm({...form,confirm_password:e.target.value})} placeholder="Enter your password again" required/></div><small className="auth-field-help">8+ characters, uppercase, lowercase, and a number.</small></label>}{mode==='login' && <div className="auth-options"><label className="check"><input type="checkbox"/> Remember me</label><button type="button" className="auth-link">Forgot password?</button></div>}{error && <p className="auth-error" role="alert">{error}</p>}<button className="auth-submit" disabled={busy}>{busy?'Securing access…':mode==='login'?'Sign in':'Create account'}<ArrowRight size={18}/></button></form><p className="auth-switch">{mode==='login'?'New to DiabeticCARE?':'Already have an account?'} <button onClick={()=>{setMode(mode==='login'?'register':'login');setError('')}}>{mode==='login'?'Create an account':'Sign in'}</button></p></section></main>;
}
